using System;
using System.Text;
using System.Collections.Generic;
using System.Globalization;
using System.Security.Cryptography;
// Process-wide immutable session profile. Installation is validate-then-swap.
public static class ContentTuning {
 sealed class Entry {public string id,type,value;public double min,max;}
 static Dictionary<string,Entry> catalog=new Dictionary<string,Entry>(StringComparer.Ordinal);
 static volatile Dictionary<string,string> active=new Dictionary<string,string>(StringComparer.Ordinal);
 static int schemaVersion=1;public static int SchemaVersion {get{return schemaVersion;}}
 static string snapshot;static readonly object gate=new object();
 static void Members(Dictionary<string,object> d,params string[] names){foreach(string k in d.Keys)if(Array.IndexOf(names,k)<0)throw new ArgumentException("Unknown JSON member "+k);foreach(string k in names)if(!d.ContainsKey(k))throw new ArgumentException("Missing JSON member "+k);}
 static string Str(object o){var s=o as string;if(s==null)throw new ArgumentException("Expected string");return s;}
 static int Integer(object o){if(!(o is double)||((double)o)%1!=0||(double)o<0||(double)o>2147483647)throw new ArgumentException("Expected nonnegative integer");return (int)(double)o;}
 static double Numeric(string s){double n;if(s.Length==0||s.Trim()!=s||!double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new ArgumentException("Expected finite number");return n;}
 static void ValidateValue(Entry e,string value){if(e.type=="text"){if(value.Length>4000)throw new ArgumentException("Text too long "+e.id);return;}if(e.type=="boolean"){if(value!="true"&&value!="false")throw new ArgumentException("Expected boolean "+e.id);return;}double n=Numeric(value);if(n<e.min||n>e.max||e.type=="integer"&&n%1!=0)throw new ArgumentException("Out of range "+e.id);}
 public static void ConfigureCatalog(string json){var root=ContentJson.Object(ContentJson.Parse(json));foreach(string k in root.Keys)if(k!="schemaVersion"&&k!="entries"&&k!="references")throw new ArgumentException("Unknown catalog member "+k);if(!root.ContainsKey("schemaVersion")||Integer(root["schemaVersion"])!=1||!root.ContainsKey("entries"))throw new ArgumentException("Unsupported catalog");var allIds=new HashSet<string>(StringComparer.Ordinal);var next=new Dictionary<string,Entry>(StringComparer.Ordinal);foreach(object o in ContentJson.Array(root["entries"])){var row=ContentJson.Object(o);Members(row,"id","group","section","title","type","defaultValue","min","max","unit","description","affects","modes","status","consumer","editable");string id=Str(row["id"]);if(!allIds.Add(id)||id.Length==0||id.Length>160)throw new ArgumentException("Invalid catalog ID");foreach(char c in id)if(c>127||!(char.IsLetterOrDigit(c)||c=='.'||c=='_'||c=='-'))throw new ArgumentException("Invalid catalog ID");if(!(row["editable"] is bool))throw new ArgumentException("Invalid editable flag");if(!(bool)row["editable"])continue;var e=new Entry{id=id,type=Str(row["type"]),value=Str(row["defaultValue"]),min=Convert.ToDouble(row["min"],CultureInfo.InvariantCulture),max=Convert.ToDouble(row["max"],CultureInfo.InvariantCulture)};if(e.type!="number"&&e.type!="integer"&&e.type!="text"&&e.type!="boolean"||next.ContainsKey(id)||e.min>e.max||Str(row["consumer"]).Length==0)throw new ArgumentException("Invalid catalog entry "+id);ValidateValue(e,e.value);next.Add(id,e);}var defaults=new Dictionary<string,string>(StringComparer.Ordinal);foreach(var e in next.Values)defaults.Add(e.id,e.value);Relations(defaults);lock(gate){catalog=next;UseDefaults();}}
 static Dictionary<string,object> Profile(string id,int revision,Dictionary<string,string> vals,int version){var rows=new List<object>();var keys=new List<string>(vals.Keys);keys.Sort(StringComparer.Ordinal);foreach(string k in keys)rows.Add(new Dictionary<string,object>{{"id",k},{"value",vals[k]}});var p=new Dictionary<string,object>{{"schemaVersion",(double)version},{"id",id},{"revision",(double)revision},{"contentHash",""},{"values",rows}};p["contentHash"]=ComputeHash(p);return p;}
 public static string ComputeHash(Dictionary<string,object> p){var vals=new SortedDictionary<string,string>(StringComparer.Ordinal);foreach(object o in ContentJson.Array(p["values"])){var row=ContentJson.Object(o);string id=Str(row["id"]);if(vals.ContainsKey(id))throw new ArgumentException("Duplicate value "+id);vals.Add(id,Str(row["value"]));}var b=new StringBuilder("content-profile-v"+Integer(p["schemaVersion"]).ToString(CultureInfo.InvariantCulture)+"\n");b.Append(Str(p["id"])).Append('\n').Append(Integer(p["revision"]).ToString(CultureInfo.InvariantCulture)).Append('\n');foreach(var row in vals)b.Append(row.Key).Append('\t').Append(Encoding.UTF8.GetByteCount(row.Value).ToString(CultureInfo.InvariantCulture)).Append(':').Append(row.Value).Append('\n');using(var sha=SHA256.Create()){byte[] hash=sha.ComputeHash(new UTF8Encoding(false,true).GetBytes(b.ToString()));var hex=new StringBuilder();foreach(byte x in hash)hex.Append(x.ToString("x2"));return hex.ToString();}}
 static Dictionary<string,string> Decode(string json,out string canonical){if(Encoding.UTF8.GetByteCount(json)>240*1024)throw new ArgumentException("Profile too large");var p=ContentJson.Object(ContentJson.Parse(json));Members(p,"schemaVersion","id","revision","contentHash","values");int version=Integer(p["schemaVersion"]);if((version!=1&&version!=2)||Integer(p["revision"])<1)throw new ArgumentException("Unsupported profile");string id=Str(p["id"]);if(id.Length<1||id.Length>64)throw new ArgumentException("Invalid profile id");foreach(char c in id)if(!(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='_'||c=='-'))throw new ArgumentException("Invalid profile id");var vals=new Dictionary<string,string>(StringComparer.Ordinal);foreach(object o in ContentJson.Array(p["values"])){var row=ContentJson.Object(o);Members(row,"id","value");string key=Str(row["id"]),v=Str(row["value"]);Entry entry;if(version==1&&key.StartsWith("choice.",StringComparison.Ordinal)||!catalog.TryGetValue(key,out entry)||vals.ContainsKey(key))throw new ArgumentException("Unknown/duplicate setting "+key);ValidateValue(entry,v);vals.Add(key,v);}int expected=0;foreach(string key in catalog.Keys)if(version==2||!key.StartsWith("choice.",StringComparison.Ordinal))expected++;if(vals.Count!=expected)throw new ArgumentException("Incomplete profile");if(Str(p["contentHash"])!=ComputeHash(p))throw new ArgumentException("Content hash mismatch");Relations(vals);canonical=ContentJson.Stringify(Profile(id,Integer(p["revision"]),vals,version));return vals;}
 static void Relations(Dictionary<string,string> v){if(v.ContainsKey("schedule.count0")&&Numeric(v["schedule.count0"])+Numeric(v["schedule.count1"])+Numeric(v["schedule.count2"])!=100)throw new ArgumentException("Request count weights must total 100");if(v.ContainsKey("schedule.progressMin")&&(Numeric(v["schedule.progressMin"])>Numeric(v["schedule.progressMax"])||Numeric(v["schedule.progressMax"])>=Numeric(v["schedule.cutoff"])))throw new ArgumentException("Invalid progress window");if(v.ContainsKey("common.required.easy")&&(Numeric(v["common.required.easy"])>Numeric(v["common.required.normal"])||Numeric(v["common.required.normal"])>Numeric(v["common.required.hard"])))throw new ArgumentException("Required satisfaction must be ordered");foreach(string prefix in new[]{"request.","type."}){bool found=false;double total=0;foreach(var row in v)if(row.Key.StartsWith(prefix,StringComparison.Ordinal)&&row.Key.EndsWith(".weight",StringComparison.Ordinal)){found=true;string enabled=row.Key.Substring(0,row.Key.Length-6)+"enabled";if(!v.ContainsKey(enabled)||v[enabled]=="true")total+=Numeric(row.Value);}if(found&&total<=0)throw new ArgumentException("No enabled weighted candidates "+prefix);}}
 public static void UseDefaults(){lock(gate){var vals=new Dictionary<string,string>(StringComparer.Ordinal);foreach(var e in catalog.Values)vals.Add(e.id,e.value);schemaVersion=catalog.ContainsKey("choice.effects.version")?2:1;active=vals;snapshot=ContentJson.Stringify(Profile("default",1,vals,schemaVersion));}}
 public static void ValidateJson(string json){lock(gate){string c;Decode(json,out c);}}
 public static void UseJson(string json){lock(gate){string c;var vals=Decode(json,out c);schemaVersion=Integer(ContentJson.Object(ContentJson.Parse(c))["schemaVersion"]);active=vals;snapshot=c;}}
 public static string UpgradeJson(string json){lock(gate){string canonical;var vals=Decode(json,out canonical);var p=ContentJson.Object(ContentJson.Parse(canonical));if(Integer(p["schemaVersion"])==2||!catalog.ContainsKey("choice.effects.version"))return canonical;foreach(var e in catalog.Values)if(e.id.StartsWith("choice.",StringComparison.Ordinal)){string value="0";if(e.id=="choice.effects.version")value="1";else if(e.id=="choice.type.Food.1.immediate.satisfaction")value=vals["effect.food.satisfaction"];else if(e.id=="choice.request.Comfort.Accept.during.motionPenaltyDelta")value=(Numeric(vals["manner.comfortMotion.penalty"])-Numeric(vals["manner.motion.penalty"])).ToString("R",CultureInfo.InvariantCulture);else {string[] parts=e.id.Split('.');if(parts.Length==7&&parts[1]=="request"&&parts[3]!="Defer"&&parts[2]!="Eta"&&parts[2]!="RejectIllegal"&&parts[4]=="end"&&(parts[5]=="success"||parts[5]=="failure")&&parts[6]=="satisfaction")value=vals["request."+parts[2]+"."+parts[5]];}ValidateValue(e,value);vals.Add(e.id,value);}string result=ContentJson.Stringify(Profile(Str(p["id"]),Integer(p["revision"]),vals,2));string checkedCanonical;Decode(result,out checkedCanonical);return checkedCanonical;}}
 public static string CaptureJson(){lock(gate){if(snapshot==null)UseDefaults();return snapshot;}}
 public static double Number(string id,double fallback){string value;return active.TryGetValue(id,out value)?Numeric(value):fallback;}
 public static int Int(string id,int fallback){return (int)Number(id,fallback);}
 public static string Text(string id,string fallback){string v;return active.TryGetValue(id,out v)&&v.Length>0?v:fallback;}
 public static string OverrideText(string id,string fallback){string value;Entry entry;return active.TryGetValue(id,out value)&&catalog.TryGetValue(id,out entry)&&value.Length>0&&value!=entry.value?value:fallback;}
 public static bool Flag(string id,bool fallback){string v;return active.TryGetValue(id,out v)?v=="true":fallback;}
}
